// Mapeia o payload da Z-API para a RPC do Supabase
const body = $json.body || {};

// Z-API envia o tipo em 'type' ou 'tipo'. Áudio vem em 'audio', 'audioUrl' ou 'url'.
const rawType = String(body.type || body.tipo || '').toLowerCase();
const isAudio = rawType === 'audio' || rawType === 'voice' || rawType === 'ptt';

const tipo = isAudio ? 'audio' : 'texto';
const urlMidia = body.audio || body.audioUrl || body.url || body.mediaUrl || null;

// Grupo: Z-API costuma enviar isGroup=true, chatId=group-id, phone=group-id, participantPhone, participantName
const isGroup = !!body.isGroup || String(body.chatId || '').endsWith('-group');

return [
  {
    json: {
      p_secret: body.secret || body.webhook_secret,
      p_instance_id: body.instance_id || body.instanceId,
      p_phone: body.phone || body.chatId,
      p_nome: body.name || body.chatName || body.profileName || body.phone,
      p_texto: isAudio ? null : (body.message || body.text || body.content),
      p_message_id: body.messageId || body.id,
      p_is_group: isGroup,
      p_chat_id: body.chatId || body.phone,
      p_photo: body.photo || body.profilePicUrl || body.groupPicture || null,
      p_participant_phone: body.participantPhone || body.author || body.sender,
      p_participant_name: body.participantName || body.participant || body.senderName,
      p_tipo: tipo,
      p_url_midia: urlMidia
    }
  }
];
